SET search_path=pg_catalog,public,extensions;
DO $t$ DECLARE x record; BEGIN FOR x IN SELECT tgname FROM pg_trigger WHERE tgrelid='"auth"."users"'::regclass AND NOT tgisinternal LOOP EXECUTE format('DROP TRIGGER %I ON "auth"."users"',x.tgname); END LOOP; END $t$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
ALTER TABLE "auth"."users" ENABLE TRIGGER "on_auth_user_created";
CREATE TRIGGER on_auth_user_created_diamonds AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION initialize_user_diamonds();
ALTER TABLE "auth"."users" ENABLE TRIGGER "on_auth_user_created_diamonds";
CREATE TRIGGER on_auth_user_created_wallet AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user_v2_create_wallet();
ALTER TABLE "auth"."users" ENABLE TRIGGER "on_auth_user_created_wallet";
-- Exact ACL TABLE: "auth"."users"
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT relowner, relacl INTO own, old_acl FROM pg_catalog.pg_class WHERE oid='"auth"."users"'::regclass;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', '"auth"."users"'; END IF;
 new_acl := '{supabase_auth_admin=arwdDxtm/supabase_auth_admin,dashboard_user=arwdDxtm/supabase_auth_admin,postgres=ar*wdDxtm/supabase_auth_admin}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', '"auth"."users"';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('r',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', '"auth"."users"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', '"auth"."users"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON TABLE "auth"."users" FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON TABLE "auth"."users" TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT relowner, relacl INTO own, actual_acl FROM pg_catalog.pg_class WHERE oid='"auth"."users"'::regclass;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    '"auth"."users"', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
DO $p$ DECLARE x record; BEGIN FOR x IN SELECT polname FROM pg_policy WHERE polrelid='"auth"."users"'::regclass LOOP EXECUTE format('DROP POLICY %I ON "auth"."users"',x.polname); END LOOP; END $p$;
