        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT ca_relation.relowner, ca_attribute.attacl INTO own, old_acl FROM pg_catalog.pg_attribute ca_attribute JOIN pg_catalog.pg_class ca_relation ON ca_relation.oid=ca_attribute.attrelid WHERE ca_attribute.attrelid='"public"."agent_commission_settlements"'::regclass AND ca_attribute.attname='period_start' AND ca_attribute.attnum>0 AND NOT ca_attribute.attisdropped;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', '"public"."agent_commission_settlements"."period_start"'; END IF;
 new_acl := NULL::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 work_old := COALESCE(old_acl,NULL::aclitem[]);
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', '"public"."agent_commission_settlements"."period_start"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', '"public"."agent_commission_settlements"."period_start"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ("period_start") ON TABLE "public"."agent_commission_settlements" FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ("period_start") ON TABLE "public"."agent_commission_settlements" TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT ca_relation.relowner, ca_attribute.attacl INTO own, actual_acl FROM pg_catalog.pg_attribute ca_attribute JOIN pg_catalog.pg_class ca_relation ON ca_relation.oid=ca_attribute.attrelid WHERE ca_attribute.attrelid='"public"."agent_commission_settlements"'::regclass AND ca_attribute.attname='period_start' AND ca_attribute.attnum>0 AND NOT ca_attribute.attisdropped;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    '"public"."agent_commission_settlements"."period_start"', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
