 END IF;
 SELECT relowner, relacl INTO own, old_acl FROM pg_catalog.pg_class WHERE oid='"public"."agent_commissions"'::regclass;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', '"public"."agent_commissions"'; END IF;
 new_acl := '{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,authenticated=r/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', '"public"."agent_commissions"';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('r',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
