DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT ca_relation.relowner, ca_attribute.attacl INTO own, old_acl FROM pg_catalog.pg_attribute ca_attribute JOIN pg_catalog.pg_class ca_relation ON ca_relation.oid=ca_attribute.attrelid WHERE ca_attribute.attrelid='"public"."club_members"'::regclass AND ca_attribute.attname='parent_agent_id' AND ca_attribute.attnum>0 AND NOT ca_attribute.attisdropped;
