-- Exact ACL TABLE: "public"."tables"
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT relowner, relacl INTO own, old_acl FROM pg_catalog.pg_class WHERE oid='"public"."tables"'::regclass;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', '"public"."tables"'; END IF;
 new_acl := '{postgres=arwdDxtm/postgres,anon=arwdxtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', '"public"."tables"';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('r',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', '"public"."tables"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', '"public"."tables"';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON TABLE "public"."tables" FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON TABLE "public"."tables" TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT relowner, relacl INTO own, actual_acl FROM pg_catalog.pg_class WHERE oid='"public"."tables"'::regclass;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    '"public"."tables"', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
DO $p$ DECLARE x record; BEGIN FOR x IN SELECT polname FROM pg_policy WHERE polrelid='"public"."tables"'::regclass LOOP EXECUTE format('DROP POLICY %I ON "public"."tables"',x.polname); END LOOP; END $p$;
CREATE POLICY "poker_arena_diamond_tables" ON "public"."tables" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM clubs c
  WHERE ((c.id = tables.club_id) AND (c.asset = 'diamonds'::text)))) AND fn_poker_can_read_games(club_id)));
CREATE POLICY "poker_arena_table_access" ON "public"."tables" AS RESTRICTIVE FOR SELECT TO "authenticated" USING ((((club_id IS NULL) AND (union_id IS NULL)) OR (COALESCE(union_id, club_id) IN ( SELECT c.id
   FROM clubs c
  WHERE fn_poker_can_read_games(c.id)))));
CREATE POLICY "poker_arena_table_guest_access" ON "public"."tables" AS RESTRICTIVE FOR SELECT TO "anon" USING (((club_id IS NULL) AND (union_id IS NULL)));
CREATE POLICY "tables_insert_owner_or_admin" ON "public"."tables" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (fn_can_create_games(club_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY "tables_select_scoped" ON "public"."tables" AS PERMISSIVE FOR SELECT TO PUBLIC USING (((COALESCE(is_private, false) = false) OR (club_id IS NULL) OR is_club_member(club_id, ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM clubs c
  WHERE ((c.id = tables.club_id) AND (c.owner_id = ( SELECT auth.uid() AS uid))))) OR fn_union_oversees_club(club_id, ( SELECT auth.uid() AS uid))));
